script:
// Excel 导出 - 完整配置示例
// 查询数据
var data = db.select("select id, username, email, phone, create_time from sys_user where is_del = 0 limit 10")

// 创建导出配置
var config = excel.createConfig("用户导出_" + excel.generateFileName(""))

// 设置表头
config.setHeaderMap({
    "username": "用户名",
    "email": "邮箱",
    "phone": "手机号",
    "create_time": "创建时间"
})

// 设置列顺序
config.setColumnOrder(["username", "email", "phone", "create_time"])

// 设置 Sheet 名称
config.setSheetName("用户列表")

// 设置自动列宽
config.setAutoWidth(true)

// 使用配置导出
excel.download(data, config)
